/* Dedicated local preview. Never obtains user media or calls a provider. */
(function(){'use strict';const $=id=>document.getElementById(id);let call,ringTimer=null,tickTimer=null;
function clear(){if(ringTimer!==null)clearTimeout(ringTimer);if(tickTimer!==null)clearInterval(tickTimer);ringTimer=tickTimer=null;}
function render(){const s=call.snapshot();$('call-state').textContent={idle:'准备演示',ringing:'模拟振铃中 · 未拨号',demo:'演示进行中 · 无真实连接',ended:'演示已结束'}[s.state];$('call-date').textContent=s.date;$('call-duration').textContent=String(Math.floor(s.seconds/60)).padStart(2,'0')+':'+String(s.seconds%60).padStart(2,'0')+' · 演示时长';$('call-ring').classList.toggle('active',s.state==='ringing');$('call-start').hidden=s.state==='ringing'||s.state==='demo';$('call-start').textContent=s.state==='ended'?'重新开始演示':'开始演示通话';$('call-end').hidden=!(s.state==='ringing'||s.state==='demo');$('call-next').hidden=s.state!=='demo';$('call-next').disabled=s.step>=3;$('call-next').textContent=['预设：看看今天吃了什么','预设：下一餐怎么记录？','预设：帮我做一个回顾','已展示全部预设回复'][s.step];$('call-note').textContent=s.state==='ended'?'本次演示已结束，没有保存任何通话或健康记录。':'';const list=$('call-transcript');list.replaceChildren();for(const row of s.messages){const li=document.createElement('li'),label=document.createElement('strong'),text=document.createElement('span');li.className=row.role;label.textContent=row.role==='user'?'沈先生 · 预设选择':'小禾 · 本机预设';text.textContent=row.text;li.append(label,text);list.append(li);}}
function stop(){clear();if(call){call.end();render();}}
try{call=window.NutriPhoneDemo.create(window.NutriHealthDemo.seed({localDate:'2026-10-22'}));render();}catch(e){$('call-state').textContent='预设加载失败，请返回助手后重试';$('call-start').disabled=true;return;}
$('call-start').addEventListener('click',()=>{clear();const s=call.start();render();ringTimer=setTimeout(()=>{ringTimer=null;if(document.hidden){stop();return;}if(call.ready(s.epoch)){render();tickTimer=setInterval(()=>{if(call.tick(s.epoch)){const t=call.snapshot().seconds;$('call-duration').textContent=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0')+' · 演示时长';}},1000);}},800);});
$('call-end').addEventListener('click',()=>{stop();$('call-start').focus();});$('call-next').addEventListener('click',()=>{call.next();render();});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});window.addEventListener('pagehide',stop);
})();
